AG_NUMBER_INIT(UnsignedChar, unsigned char, _unsigned, unsigned long long)
AG_NUMBER_INIT(UnsignedShort, unsigned short, _unsigned, unsigned long long)
AG_NUMBER_INIT(UnsignedInt, unsigned int, _unsigned, unsigned long long)
AG_NUMBER_INIT(UnsignedLong, unsigned long, _unsigned, unsigned long long)
AG_NUMBER_INIT(UnsignedLongLong, unsigned long long, _unsigned, unsigned long long)
