@implementation AGNumberBoolean

AG_NUMBER_INIT(Bool, BOOL, _flag, BOOL)

/* A boolean answers its flag and the numbers it stands for, which is how one class serves both
 * -boolValue and the fifteen conversions without a special case in the reader. */
- (unsigned char)agKind
{
	return _kind;
}

- (long long)longLongValue
{
	return _flag ? 1 : 0;
}

- (unsigned long long)unsignedLongLongValue
{
	return _flag ? 1ULL : 0ULL;
}

- (double)doubleValue
{
	return _flag ? 1.0 : 0.0;
}

@end
